52	// R2/R3: the final audit does not rerun a pure read while its commit stands, reruns every
53	// other command, and reruns a head-relative read, and finds the change, when HEAD moved.
54	func TestTheFinalAuditSkipsPureReadsWhileTheirCommitStandsAndOnlyThen(t *testing.T) {
55		root := snapshotRepo(t, map[string]string{"a.md": "one\n", "b.md": "two\n"})
56		reruns := map[string]*atomic.Int64{}
57		original := governanceAuditGit
58		governanceAuditGit = func(ctx context.Context, files Files, r string, args []string, limit int64) ([]byte, []byte, error) {
59			key := strings.Join(args, " ")
60			if reruns[key] == nil {
61				reruns[key] = &atomic.Int64{}
62			}
63			reruns[key].Add(1)
64			return original(ctx, files, r, args, limit)
65		}
66		defer func() { governanceAuditGit = original }()
67	
68		capture := func() (*governanceReadView, Store, string) {
69			base, view := (Store{Root: root}).beginGovernanceReadView()
70			store := base.withGovernanceReadView(view, "pure-test")
71			head, err := captureGovernanceGit(store.fsys(), root, "pure-test", "rev-parse", "--verify", "HEAD")
72			if err != nil {
73				t.Fatal(err)
74			}
75			id := strings.TrimSpace(string(head))
76			for _, args := range [][]string{
77				{"log", "-1", "--format=%H", "--", "a.md"},
78				{"show", id + ":a.md"},
79				{"ls-tree", "-z", "HEAD", "--", "a.md"},
80			} {
81				if _, err := captureGovernanceGit(store.fsys(), root, "pure-test", args...); err != nil {
82					t.Fatalf("%v: %v", args, err)
83				}
84			}
85			return view, store, id
86		}
87		count := func(prefix string) int64 {
88			var n int64
89			for key, c := range reruns {
90				if strings.HasPrefix(key, prefix) {
91					n += c.Load()
92				}
93			}
94			return n
95		}
96	
97		view, _, _ := capture()
98		if audit := view.audit(); len(audit.ChangedPaths) != 0 || audit.ChangedProducers["pure-test"] {
99			t.Fatalf("nothing changed, the audit reports it did: %+v", audit)
100		}
101		if got := count("log -1"); got != 0 {
102			t.Fatalf("the head-relative log was rerun %d times with HEAD where it was", got)
103		}
104		if got := count("show "); got != 0 {
105			t.Fatalf("the object-id show was rerun %d times", got)
106		}
107		if count("rev-parse") == 0 || count("ls-tree") == 0 {
108			t.Fatalf("a command that is not pure was not rerun: %v", reruns)
109		}
110	
111		// HEAD moves, a.md changes: the log, rerun, shows a different last commit.
112		view, _, _ = capture()
113		if err := os.WriteFile(filepath.Join(root, "a.md"), []byte("one changed\n"), 0o644); err != nil {
114			t.Fatal(err)
115		}
116		snapshotTestGit(t, root, "add", "a.md")
117		snapshotTestGit(t, root, "commit", "-q", "-m", "change a")
118		before := count("log -1")
119		audit := view.audit()
120		if count("log -1") != before+1 {
121			t.Fatalf("the head-relative log was not rerun after HEAD moved")
122		}
123		if !audit.ChangedProducers["pure-test"] || len(audit.ChangedPaths) == 0 {
124			t.Fatalf("the change after HEAD moved was not found: %+v", audit)
125		}
126	}
