564	func runGovernanceGitCommandOutputAdmittedContext(ctx context.Context, files Files, root string, args []string, limit int64, admit func(int64) bool) ([]byte, []byte, error) {
565		if limit < 0 {
566			return nil, nil, errGovernanceReadViewBudget
