568		files = FilesOrNative(files)
569		if ctx == nil {
570			ctx = context.Background()
571		}
572		cmd := gitCommandContext(ctx, append([]string{"--no-replace-objects", "-C", root}, args...)...)
573		cmd.WaitDelay = 2 * time.Second
574		cmd.Env = append(cmd.Env, "GIT_OPTIONAL_LOCKS=0")
575		output := &boundedGovernanceGitOutput{limit: limit, admit: admit}
576		cmd.Stdout = governanceGitStream{output: output, stderr: false}
577		cmd.Stderr = governanceGitStream{output: output, stderr: true}
578		err := cmd.Run()
579		stdout, stderr, exceeded := output.values()
580		if exceeded {
581			return nil, nil, errGovernanceReadViewBudget
582		}
583		if err != nil {
584			if exit, ok := err.(*exec.ExitError); ok {
585				exit.Stderr = append([]byte(nil), stderr...)
586			}
587			return stdout, stderr, &GitSnapshotError{Operation: strings.Join(args, " "), Cause: err}
588		}
589		if len(stderr) > 0 {
590			detail := strings.TrimSpace(string(stderr))
591			if detail == "" {
592				detail = "Git wrote unclassified stderr output"
593			}
594			return stdout, stderr, &GitSnapshotError{Operation: strings.Join(args, " "), Cause: errors.New(detail)}
595		}
596		return stdout, stderr, nil
597	}
